/**
 * issue #88: generic, node-type-agnostic Temporal heartbeat wrapper around
 * `activities.js`'s `executeNode`.
 *
 * `activities.js` is deliberately framework-agnostic - it must never import
 * `@temporalio/activity` or otherwise become Temporal-aware (see that file's
 * docblock and AGENTS.md's architecture rules). This module is the seam
 * where Temporal-specific heartbeat behavior belongs instead: it wraps the
 * existing `executeNode` Activity implementation from the OUTSIDE, in the
 * Temporal-specific worker registration layer (`worker.js`), without
 * inspecting `msg`/node type/config at all.
 *
 *     Temporal Activity wrapper
 *         |-- heartbeat periodically while executeNode() is pending
 *         `-- await existing executeNode()
 *                  |
 *             Capture / live Node-RED node
 *
 * What heartbeats mean here: ONLY that this Activity worker/process is
 * still alive and the pending invocation is still being observed. They do
 * NOT mean exactly-once execution, cancellation of the in-flight Node-RED
 * invocation, extension of `startToCloseTimeout`, or any semantic progress
 * signal from inside an arbitrary node. If a worker dies mid-node, Temporal
 * may still retry the Activity and re-run the node, exactly as before
 * (at-least-once, unchanged - see worker.js's own at-least-once docblock).
 *
 * Event-loop limitation (documented, not fixed here): a timer-based
 * heartbeat cannot fire while a node blocks the Node.js event loop
 * synchronously. Async long-running nodes (HTTP calls, Agent nodes, Exec
 * nodes awaiting a subprocess, etc.) get heartbeats for free; a CPU-bound or
 * otherwise synchronously-blocking node may still hit the heartbeat
 * timeout. This issue does not add worker threads or per-node-type progress
 * APIs to work around that.
 */

"use strict";

/**
 * Wraps `executeNode` so that, while one invocation is pending, a heartbeat
 * callback fires on a fixed interval - and always stops (via `clearInterval`
 * in `finally`) once the invocation settles, whether it resolves, rejects,
 * or the wrapper itself is torn down by that same code path. The wrapped
 * function's resolved value or thrown error is passed through completely
 * unchanged; the wrapper never inspects `input` (flowVersion/nodeId/msg/
 * httpBridge/...) beyond forwarding it and, for the heartbeat detail only,
 * reading `input.nodeId` (small, non-sensitive - never `msg` contents).
 *
 * DI seams (both optional, both here only so unit tests can run with fake
 * timers/callbacks instead of real sleeping):
 *   - `heartbeat(detail)`: called on every tick. Defaults to
 *     `Context.current().heartbeat(detail)` from `@temporalio/activity`,
 *     resolved lazily inside the returned function (not at module load
 *     time) so this module itself never needs a live Activity context just
 *     to be required.
 *   - `setIntervalFn`/`clearIntervalFn`: default to the real
 *     `setInterval`/`clearInterval`.
 *
 * A heartbeat callback that itself throws/rejects synchronously is caught
 * and swallowed (a missed heartbeat can at most cause Temporal to detect
 * the heartbeat timeout - it must never turn into an unrelated/duplicate
 * rejection that masks the real `executeNode` result). Nothing about a
 * heartbeat failure changes what the wrapped `executeNode` resolves/throws.
 *
 * @param {function} executeNode - the framework-agnostic Activity from
 *   `activities.js`'s `createExecuteNode(...)`.
 * @param {Object} [options]
 * @param {number} [options.intervalMs=20000] - heartbeat interval, ms.
 * @param {function} [options.heartbeat] - `(detail) => void`, DI seam.
 * @param {function} [options.setIntervalFn] - DI seam, defaults to `setInterval`.
 * @param {function} [options.clearIntervalFn] - DI seam, defaults to `clearInterval`.
 * @returns {function(Object): Promise<Object>} heartbeating `executeNode`.
 */
function createHeartbeatingExecuteNode(executeNode, options) {
    var opts = options || {};
    var intervalMs = opts.intervalMs || 20000;
    var setIntervalFn = opts.setIntervalFn || setInterval;
    var clearIntervalFn = opts.clearIntervalFn || clearInterval;
    var heartbeatFn = opts.heartbeat || defaultHeartbeat;

    return function heartbeatingExecuteNode(input) {
        var detail = input && input.nodeId ? { nodeId: input.nodeId } : undefined;
        var timer = setIntervalFn(function() {
            try {
                heartbeatFn(detail);
            } catch (err) {
                // A failed heartbeat call must never surface as the
                // Activity's own result - Temporal will simply detect the
                // missed heartbeat via `heartbeatTimeout` on its own.
            }
        }, intervalMs);

        var result;
        try {
            result = Promise.resolve(executeNode(input));
        } catch (err) {
            result = Promise.reject(err);
        }
        return result.finally(function() {
            clearIntervalFn(timer);
        });
    };
}

/**
 * Default production heartbeat: `Context.current().heartbeat(detail)` from
 * `@temporalio/activity`. Resolved lazily (required on first call, not at
 * module load) so this module never needs a live Activity execution context
 * just to be `require`d (e.g. from plain unit tests).
 */
function defaultHeartbeat(detail) {
    var Context = require("@temporalio/activity").Context;
    Context.current().heartbeat(detail);
}

module.exports = { createHeartbeatingExecuteNode };
